import React, { createContext, useContext, useState, useCallback, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { v4 as uuidv4 } from 'uuid';

// Create the notification context
const NotificationContext = createContext();
NotificationContext.displayName = 'NotificationContext';

// Custom hook for using the notification context
export function useNotification() {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotification must be used within a NotificationProvider');
  }
  return context;
}

// Toast Notification Component - Memoized for better performance
const Toast = React.memo(({ notification, onDismiss }) => {
  const { id, message, type, progress } = notification;
  
  // Ref for timer management
  const timerRef = useRef(null);
  
  // Setup auto-dismiss timer
  useEffect(() => {
    if (notification.duration > 0) {
      timerRef.current = setTimeout(() => {
        onDismiss(id);
      }, notification.duration);
    }
    
    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
      }
    };
  }, [id, notification.duration, onDismiss]);
  
  // Style mapping for different notification types
  const getNotificationStyle = (type) => {
    switch(type) {
      case 'success':
        return 'bg-gradient-to-r from-green-500 to-emerald-600 text-white';
      case 'error':
        return 'bg-gradient-to-r from-red-500 to-rose-600 text-white';
      case 'warning':
        return 'bg-gradient-to-r from-amber-500 to-orange-600 text-white';
      case 'info':
      default:
        return 'bg-gradient-to-r from-blue-500 to-indigo-600 text-white';
    }
  };

  // Icon mapping for different notification types
  const getIcon = (type) => {
    switch(type) {
      case 'success':
        return (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
          </svg>
        );
      case 'error':
        return (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        );
      case 'warning':
        return (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
        );
      case 'info':
      default:
        return (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        );
    }
  };

  // Handle manually dismissing the notification
  const handleDismiss = useCallback(() => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
    }
    onDismiss(id);
  }, [onDismiss, id]);

  return (
    <motion.div
      className={`${getNotificationStyle(type)} rounded-xl shadow-xl p-3 mb-2 max-w-md flex items-center justify-between backdrop-blur-sm border border-white/10`}
      initial={{ opacity: 0, y: -20, scale: 0.9 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, scale: 0.9, transition: { duration: 0.2 } }}
      layout
    >
      <div className="flex items-center space-x-2">
        {getIcon(type)}
        <span className="text-sm font-medium">{message}</span>
      </div>
      
      {/* Progress indicator for auto-dismiss timing */}
      {notification.duration > 0 && (
        <motion.div 
          className="absolute bottom-0 left-0 h-1 bg-white/30 rounded-b-xl"
          initial={{ width: "100%" }}
          animate={{ width: "0%" }}
          transition={{ duration: notification.duration / 1000, ease: "linear" }}
          style={{ transformOrigin: "left" }}
        />
      )}
      
      <button
        onClick={handleDismiss}
        className="ml-3 text-white/80 hover:text-white focus:outline-none transition-colors"
        aria-label="Dismiss notification"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>
    </motion.div>
  );
});

Toast.displayName = 'Toast';

// Generate a unique ID for notifications
const generateId = () => `notification-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

// Notification provider component
export function NotificationProvider({ children }) {
  const [notifications, setNotifications] = useState([]);
  const [autoNotify, setAutoNotify] = useState(() => {
    try {
      const savedPref = localStorage.getItem('autoNotify');
      return savedPref === null ? true : savedPref === 'true';
    } catch (error) {
      console.error('Error accessing localStorage:', error);
      return true;
    }
  });
  const notificationQueue = useRef([]);
  const isProcessing = useRef(false);
  
  // Save autoNotify preference to localStorage
  useEffect(() => {
    try {
      localStorage.setItem('autoNotify', autoNotify.toString());
    } catch (error) {
      console.error('Error saving to localStorage:', error);
    }
  }, [autoNotify]);
  
  // Process the notification queue to prevent flooding the UI
  const processQueue = useCallback(() => {
    if (isProcessing.current) return;
    if (notificationQueue.current.length === 0) return;
    
    isProcessing.current = true;
    
    // Take the next notification from the queue
    const nextNotification = notificationQueue.current.shift();
    
    // Add it to the state
    setNotifications(prevNotifications => [...prevNotifications, nextNotification]);
    
    // Set a small delay before processing the next one to create a staggered effect
    setTimeout(() => {
      isProcessing.current = false;
      processQueue();
    }, 150);
  }, []);

  // Add a new notification with debouncing to prevent UI flooding
  const addNotification = useCallback((message, type = 'info', duration = 3000) => {
    const newNotification = {
      id: generateId(),
      message,
      type,
      duration,
      timestamp: Date.now()
    };
    
    // Add to queue
    notificationQueue.current.push(newNotification);
    
    // Start processing if not already
    processQueue();
    
    return newNotification.id;
  }, [processQueue]);

  // Toggle automatic notifications
  const toggleAutoNotify = useCallback(() => {
    setAutoNotify(prev => !prev);
  }, []);

  // Dismiss a notification by ID
  const dismissNotification = useCallback((id) => {
    setNotifications(prevNotifications => 
      prevNotifications.filter(notification => notification.id !== id)
    );
  }, []);

  // Clear all notifications
  const clearNotifications = useCallback(() => {
    setNotifications([]);
    notificationQueue.current = [];
  }, []);
  
  // Limit max notifications shown at once
  useEffect(() => {
    const MAX_VISIBLE = 5;
    if (notifications.length > MAX_VISIBLE) {
      // Remove oldest notifications
      const sorted = [...notifications].sort((a, b) => a.timestamp - b.timestamp);
      const toRemove = sorted.slice(0, notifications.length - MAX_VISIBLE);
      toRemove.forEach(notification => {
        dismissNotification(notification.id);
      });
    }
  }, [notifications, dismissNotification]);

  // Create notification value
  const value = {
    notifications,
    addNotification,
    dismissNotification,
    clearNotifications,
    autoNotify,
    toggleAutoNotify
  };

  return (
    <NotificationContext.Provider value={value}>
      {children}
      {/* Toast Container */}
      <div className="fixed top-4 right-4 z-50 flex flex-col items-end space-y-2 pointer-events-none">
        <AnimatePresence mode="popLayout">
          {notifications.map(notification => (
            <div key={notification.id} className="pointer-events-auto">
              <Toast 
                notification={notification} 
                onDismiss={dismissNotification} 
              />
            </div>
          ))}
        </AnimatePresence>
      </div>
    </NotificationContext.Provider>
  );
} 